/bin/zsh -lc "python3 -B - <<'PY'
from copy import deepcopy
from ledger import Ledger

for value in (-1, True, 1.5):
    try:
        Ledger({'a': value})
    except ValueError:
        print(f'constructor balance {value"'!r}: rejected'"')
    else:
        print(f'REPRODUCED: constructor accepted invalid balance {value"'!r}'"')

for label, action in [
    ('negative amount', lambda ledger: ledger.transfer('a', 'b', -5, 'bad')),
    ('missing target', lambda ledger: ledger.transfer('a', 'missing', 5, 'bad')),
    ('malformed batch entry', lambda ledger: ledger.batch([
        dict(source='a', target='b', amount=5, key='first'), {}])),
]:
    ledger = Ledger({'a': 10, 'b': 0})
    before = deepcopy((ledger.balances, ledger.history))
    try:
        action(ledger)
    except Exception as error:
        result = type(error).__name__
    else:
        result = 'accepted'
    print(f'REPRODUCED: {label}: {result}; state changed={(ledger.balances, ledger.history) "'!= before}'"')
PY"

